from jsonb_to_recordset($problem_data$[{"code":"squad-5733be284776f41900661182","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: University of Notre Dame]\nArchitecturally, the school has a Catholic character. Atop the Main Building's gold dome is a golden statue of the Virgin Mary. Immediately in front of the Main Building and facing it, is a copper statue of Christ with arms upraised with the legend \"Venite Ad Me Omnes\". Next to the Main Building is the Basilica of the Sacred Heart. Immediately behind the basilica is the Grotto, a Marian place of prayer and reflection. It is a replica of the grotto at Lourdes, France where the Virgin Mary reputedly appeared to Saint Bernadette Soubirous in 1858. At the end of the main drive (and in a direct line that connects through 3 statues and the Gold Dome), is a simple, modern stone statue of Mary.\n\n[Question]\nTo whom did the Virgin Mary allegedly appear in 1858 in Lourdes France?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"Saint Bernadette Soubirous","explanation":"It is a replica of the grotto at Lourdes, France where the Virgin Mary reputedly appeared to Saint Bernadette Soubirous in 1858.","tags":["영어 독해","reading comprehension","University of Notre Dame","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-5733be284776f4190066117f","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: University of Notre Dame]\nArchitecturally, the school has a Catholic character. Atop the Main Building's gold dome is a golden statue of the Virgin Mary. Immediately in front of the Main Building and facing it, is a copper statue of Christ with arms upraised with the legend \"Venite Ad Me Omnes\". Next to the Main Building is the Basilica of the Sacred Heart. Immediately behind the basilica is the Grotto, a Marian place of prayer and reflection. It is a replica of the grotto at Lourdes, France where the Virgin Mary reputedly appeared to Saint Bernadette Soubirous in 1858. At the end of the main drive (and in a direct line that connects through 3 statues and the Gold Dome), is a simple, modern stone statue of Mary.\n\n[Question]\nWhat is in front of the Notre Dame Main Building?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"a copper statue of Christ","explanation":"Immediately in front of the Main Building and facing it, is a copper statue of Christ with arms upraised with the legend \"Venite Ad Me Omnes\".","tags":["영어 독해","reading comprehension","University of Notre Dame","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-5733be284776f41900661180","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: University of Notre Dame]\nArchitecturally, the school has a Catholic character. Atop the Main Building's gold dome is a golden statue of the Virgin Mary. Immediately in front of the Main Building and facing it, is a copper statue of Christ with arms upraised with the legend \"Venite Ad Me Omnes\". Next to the Main Building is the Basilica of the Sacred Heart. Immediately behind the basilica is the Grotto, a Marian place of prayer and reflection. It is a replica of the grotto at Lourdes, France where the Virgin Mary reputedly appeared to Saint Bernadette Soubirous in 1858. At the end of the main drive (and in a direct line that connects through 3 statues and the Gold Dome), is a simple, modern stone statue of Mary.\n\n[Question]\nThe Basilica of the Sacred heart at Notre Dame is beside to which structure?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"the Main Building","explanation":"Next to the Main Building is the Basilica of the Sacred Heart.","tags":["영어 독해","reading comprehension","University of Notre Dame","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-5733be284776f41900661181","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: University of Notre Dame]\nArchitecturally, the school has a Catholic character. Atop the Main Building's gold dome is a golden statue of the Virgin Mary. Immediately in front of the Main Building and facing it, is a copper statue of Christ with arms upraised with the legend \"Venite Ad Me Omnes\". Next to the Main Building is the Basilica of the Sacred Heart. Immediately behind the basilica is the Grotto, a Marian place of prayer and reflection. It is a replica of the grotto at Lourdes, France where the Virgin Mary reputedly appeared to Saint Bernadette Soubirous in 1858. At the end of the main drive (and in a direct line that connects through 3 statues and the Gold Dome), is a simple, modern stone statue of Mary.\n\n[Question]\nWhat is the Grotto at Notre Dame?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"a Marian place of prayer and reflection","explanation":"Immediately behind the basilica is the Grotto, a Marian place of prayer and reflection.","tags":["영어 독해","reading comprehension","University of Notre Dame","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-5733be284776f4190066117e","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: University of Notre Dame]\nArchitecturally, the school has a Catholic character. Atop the Main Building's gold dome is a golden statue of the Virgin Mary. Immediately in front of the Main Building and facing it, is a copper statue of Christ with arms upraised with the legend \"Venite Ad Me Omnes\". Next to the Main Building is the Basilica of the Sacred Heart. Immediately behind the basilica is the Grotto, a Marian place of prayer and reflection. It is a replica of the grotto at Lourdes, France where the Virgin Mary reputedly appeared to Saint Bernadette Soubirous in 1858. At the end of the main drive (and in a direct line that connects through 3 statues and the Gold Dome), is a simple, modern stone statue of Mary.\n\n[Question]\nWhat sits on top of the Main Building at Notre Dame?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"a golden statue of the Virgin Mary","explanation":"Atop the Main Building's gold dome is a golden statue of the Virgin Mary.","tags":["영어 독해","reading comprehension","University of Notre Dame","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-5733bf84d058e614000b61be","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"응용","question":"[Passage: University of Notre Dame]\nAs at most other universities, Notre Dame's students run a number of news media outlets. The nine student-run outlets include three newspapers, both a radio and television station, and several magazines and journals. Begun as a one-page journal in September 1876, the Scholastic magazine is issued twice monthly and claims to be the oldest continuous collegiate publication in the United States. The other magazine, The Juggler, is released twice a year and focuses on student literature and artwork. The Dome yearbook is published annually. The newspapers have varying publication interests, with The Observer published daily and mainly reporting university and other news, and staffed by students from both Notre Dame and Saint Mary's College. Unlike Scholastic and The Dome, The Observer is an independent publication and does not have a faculty advisor or any editorial oversight from the University. In 1987, when some students believed that The Observer began to show a conservative bias, a liberal newspaper, Common Sense was published. Likewise, in 2003, when other students believed that the paper showed a liberal bias, the conservative paper Irish Rover went into production. Neither paper is published as often as The Observer; however, all three are distributed to all students. Finally, in Spring 2008 an undergraduate journal for political science research, Beyond Politics, made its debut.\n\n[Question]\nWhen did the Scholastic Magazine of Notre dame begin publishing?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"September 1876","explanation":"Begun as a one-page journal in September 1876, the Scholastic magazine is issued twice monthly and claims to be the oldest continuous collegiate publication in the United States.","tags":["영어 독해","reading comprehension","University of Notre Dame","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-5733bf84d058e614000b61bf","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"응용","question":"[Passage: University of Notre Dame]\nAs at most other universities, Notre Dame's students run a number of news media outlets. The nine student-run outlets include three newspapers, both a radio and television station, and several magazines and journals. Begun as a one-page journal in September 1876, the Scholastic magazine is issued twice monthly and claims to be the oldest continuous collegiate publication in the United States. The other magazine, The Juggler, is released twice a year and focuses on student literature and artwork. The Dome yearbook is published annually. The newspapers have varying publication interests, with The Observer published daily and mainly reporting university and other news, and staffed by students from both Notre Dame and Saint Mary's College. Unlike Scholastic and The Dome, The Observer is an independent publication and does not have a faculty advisor or any editorial oversight from the University. In 1987, when some students believed that The Observer began to show a conservative bias, a liberal newspaper, Common Sense was published. Likewise, in 2003, when other students believed that the paper showed a liberal bias, the conservative paper Irish Rover went into production. Neither paper is published as often as The Observer; however, all three are distributed to all students. Finally, in Spring 2008 an undergraduate journal for political science research, Beyond Politics, made its debut.\n\n[Question]\nHow often is Notre Dame's the Juggler published?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"twice","explanation":"The other magazine, The Juggler, is released twice a year and focuses on student literature and artwork.","tags":["영어 독해","reading comprehension","University of Notre Dame","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-5733bf84d058e614000b61c0","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"응용","question":"[Passage: University of Notre Dame]\nAs at most other universities, Notre Dame's students run a number of news media outlets. The nine student-run outlets include three newspapers, both a radio and television station, and several magazines and journals. Begun as a one-page journal in September 1876, the Scholastic magazine is issued twice monthly and claims to be the oldest continuous collegiate publication in the United States. The other magazine, The Juggler, is released twice a year and focuses on student literature and artwork. The Dome yearbook is published annually. The newspapers have varying publication interests, with The Observer published daily and mainly reporting university and other news, and staffed by students from both Notre Dame and Saint Mary's College. Unlike Scholastic and The Dome, The Observer is an independent publication and does not have a faculty advisor or any editorial oversight from the University. In 1987, when some students believed that The Observer began to show a conservative bias, a liberal newspaper, Common Sense was published. Likewise, in 2003, when other students believed that the paper showed a liberal bias, the conservative paper Irish Rover went into production. Neither paper is published as often as The Observer; however, all three are distributed to all students. Finally, in Spring 2008 an undergraduate journal for political science research, Beyond Politics, made its debut.\n\n[Question]\nWhat is the daily student paper at Notre Dame called?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"The Observer","explanation":"The newspapers have varying publication interests, with The Observer published daily and mainly reporting university and other news, and staffed by students from both Notre Dame and Saint Mary's College.","tags":["영어 독해","reading comprehension","University of Notre Dame","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-5733bf84d058e614000b61bd","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"응용","question":"[Passage: University of Notre Dame]\nAs at most other universities, Notre Dame's students run a number of news media outlets. The nine student-run outlets include three newspapers, both a radio and television station, and several magazines and journals. Begun as a one-page journal in September 1876, the Scholastic magazine is issued twice monthly and claims to be the oldest continuous collegiate publication in the United States. The other magazine, The Juggler, is released twice a year and focuses on student literature and artwork. The Dome yearbook is published annually. The newspapers have varying publication interests, with The Observer published daily and mainly reporting university and other news, and staffed by students from both Notre Dame and Saint Mary's College. Unlike Scholastic and The Dome, The Observer is an independent publication and does not have a faculty advisor or any editorial oversight from the University. In 1987, when some students believed that The Observer began to show a conservative bias, a liberal newspaper, Common Sense was published. Likewise, in 2003, when other students believed that the paper showed a liberal bias, the conservative paper Irish Rover went into production. Neither paper is published as often as The Observer; however, all three are distributed to all students. Finally, in Spring 2008 an undergraduate journal for political science research, Beyond Politics, made its debut.\n\n[Question]\nHow many student news papers are found at Notre Dame?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"three","explanation":"The nine student-run outlets include three newspapers, both a radio and television station, and several magazines and journals.","tags":["영어 독해","reading comprehension","University of Notre Dame","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-5733bf84d058e614000b61c1","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"응용","question":"[Passage: University of Notre Dame]\nAs at most other universities, Notre Dame's students run a number of news media outlets. The nine student-run outlets include three newspapers, both a radio and television station, and several magazines and journals. Begun as a one-page journal in September 1876, the Scholastic magazine is issued twice monthly and claims to be the oldest continuous collegiate publication in the United States. The other magazine, The Juggler, is released twice a year and focuses on student literature and artwork. The Dome yearbook is published annually. The newspapers have varying publication interests, with The Observer published daily and mainly reporting university and other news, and staffed by students from both Notre Dame and Saint Mary's College. Unlike Scholastic and The Dome, The Observer is an independent publication and does not have a faculty advisor or any editorial oversight from the University. In 1987, when some students believed that The Observer began to show a conservative bias, a liberal newspaper, Common Sense was published. Likewise, in 2003, when other students believed that the paper showed a liberal bias, the conservative paper Irish Rover went into production. Neither paper is published as often as The Observer; however, all three are distributed to all students. Finally, in Spring 2008 an undergraduate journal for political science research, Beyond Politics, made its debut.\n\n[Question]\nIn what year did the student paper Common Sense begin publication at Notre Dame?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"1987","explanation":"In 1987, when some students believed that The Observer began to show a conservative bias, a liberal newspaper, Common Sense was published.","tags":["영어 독해","reading comprehension","University of Notre Dame","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56d9cadedc89441400fdb82c","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Dog]\nThere are a vast range of commodity forms available to transform a pet dog into an ideal companion. The list of goods, services and places available is enormous: from dog perfumes, couture, furniture and housing, to dog groomers, therapists, trainers and caretakers, dog cafes, spas, parks and beaches, and dog hotels, airlines and cemeteries. While dog training as an organized activity can be traced back to the 18th century, in the last decades of the 20th century it became a high profile issue as many normal dog behaviors such as barking, jumping up, digging, rolling in dung, fighting, and urine marking (which dogs do to establish territory through scent), became increasingly incompatible with the new role of a pet dog. Dog training books, classes and television programs proliferated as the process of commodifying the pet dog continued.\n\n[Question]\nHow far back can dog training be found?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"18th century","explanation":"While dog training as an organized activity can be traced back to the 18th century, in the last decades of the 20th century it became a high profile issue as many normal dog behaviors such as barking, jumping up, digging, rolling in dung, fighting, and urine marking (which dogs do to establish territory through scent), became increasingly incompatible with the new role of a pet dog.","tags":["영어 독해","reading comprehension","Dog","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56d9cadedc89441400fdb82d","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Dog]\nThere are a vast range of commodity forms available to transform a pet dog into an ideal companion. The list of goods, services and places available is enormous: from dog perfumes, couture, furniture and housing, to dog groomers, therapists, trainers and caretakers, dog cafes, spas, parks and beaches, and dog hotels, airlines and cemeteries. While dog training as an organized activity can be traced back to the 18th century, in the last decades of the 20th century it became a high profile issue as many normal dog behaviors such as barking, jumping up, digging, rolling in dung, fighting, and urine marking (which dogs do to establish territory through scent), became increasingly incompatible with the new role of a pet dog. Dog training books, classes and television programs proliferated as the process of commodifying the pet dog continued.\n\n[Question]\nHow do dogs mark their territory?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"urine marking","explanation":"While dog training as an organized activity can be traced back to the 18th century, in the last decades of the 20th century it became a high profile issue as many normal dog behaviors such as barking, jumping up, digging, rolling in dung, fighting, and urine marking (which dogs do to establish territory through scent), became increasingly incompatible with the new role of a pet dog.","tags":["영어 독해","reading comprehension","Dog","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56d9cadedc89441400fdb82e","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Dog]\nThere are a vast range of commodity forms available to transform a pet dog into an ideal companion. The list of goods, services and places available is enormous: from dog perfumes, couture, furniture and housing, to dog groomers, therapists, trainers and caretakers, dog cafes, spas, parks and beaches, and dog hotels, airlines and cemeteries. While dog training as an organized activity can be traced back to the 18th century, in the last decades of the 20th century it became a high profile issue as many normal dog behaviors such as barking, jumping up, digging, rolling in dung, fighting, and urine marking (which dogs do to establish territory through scent), became increasingly incompatible with the new role of a pet dog. Dog training books, classes and television programs proliferated as the process of commodifying the pet dog continued.\n\n[Question]\nWhat has become important to ensure dogs do not do things that humans don't want them to do, such as jumping?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"training","explanation":"While dog training as an organized activity can be traced back to the 18th century, in the last decades of the 20th century it became a high profile issue as many normal dog behaviors such as barking, jumping up, digging, rolling in dung, fighting, and urine marking (which dogs do to establish territory through scent), became increasingly incompatible with the new role of a pet dog.","tags":["영어 독해","reading comprehension","Dog","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56d62ca31c85041400946f74","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Dog]\nThe majority of contemporary people with dogs describe their pet as part of the family, although some ambivalence about the relationship is evident in the popular reconceptualization of the dog–human family as a pack. A dominance model of dog–human relationships has been promoted by some dog trainers, such as on the television program Dog Whisperer. However it has been disputed that \"trying to achieve status\" is characteristic of dog–human interactions. Pet dogs play an active role in family life; for example, a study of conversations in dog–human families showed how family members use the dog as a resource, talking to the dog, or talking through the dog, to mediate their interactions with each other.\n\n[Question]\nHow do most people describe the relationship with their dogs?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"part of the family","explanation":"The majority of contemporary people with dogs describe their pet as part of the family, although some ambivalence about the relationship is evident in the popular reconceptualization of the dog–human family as a pack.","tags":["영어 독해","reading comprehension","Dog","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56d62ca31c85041400946f75","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Dog]\nThe majority of contemporary people with dogs describe their pet as part of the family, although some ambivalence about the relationship is evident in the popular reconceptualization of the dog–human family as a pack. A dominance model of dog–human relationships has been promoted by some dog trainers, such as on the television program Dog Whisperer. However it has been disputed that \"trying to achieve status\" is characteristic of dog–human interactions. Pet dogs play an active role in family life; for example, a study of conversations in dog–human families showed how family members use the dog as a resource, talking to the dog, or talking through the dog, to mediate their interactions with each other.\n\n[Question]\nWhat television show uses a dominance model of dog and human relationships?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"Dog Whisperer.","explanation":"A dominance model of dog–human relationships has been promoted by some dog trainers, such as on the television program Dog Whisperer. However it has been disputed that \"trying to achieve status\" is characteristic of dog–human interactions.","tags":["영어 독해","reading comprehension","Dog","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56d9cb52dc89441400fdb83c","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Dog]\nThe majority of contemporary people with dogs describe their pet as part of the family, although some ambivalence about the relationship is evident in the popular reconceptualization of the dog–human family as a pack. A dominance model of dog–human relationships has been promoted by some dog trainers, such as on the television program Dog Whisperer. However it has been disputed that \"trying to achieve status\" is characteristic of dog–human interactions. Pet dogs play an active role in family life; for example, a study of conversations in dog–human families showed how family members use the dog as a resource, talking to the dog, or talking through the dog, to mediate their interactions with each other.\n\n[Question]\nMost people today describe their dogs as what?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"part of the family","explanation":"The majority of contemporary people with dogs describe their pet as part of the family, although some ambivalence about the relationship is evident in the popular reconceptualization of the dog–human family as a pack.","tags":["영어 독해","reading comprehension","Dog","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56d9cb52dc89441400fdb83d","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Dog]\nThe majority of contemporary people with dogs describe their pet as part of the family, although some ambivalence about the relationship is evident in the popular reconceptualization of the dog–human family as a pack. A dominance model of dog–human relationships has been promoted by some dog trainers, such as on the television program Dog Whisperer. However it has been disputed that \"trying to achieve status\" is characteristic of dog–human interactions. Pet dogs play an active role in family life; for example, a study of conversations in dog–human families showed how family members use the dog as a resource, talking to the dog, or talking through the dog, to mediate their interactions with each other.\n\n[Question]\nWhat TV show promotes a dominance model for the relationships people have with their dogs?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"Dog Whisperer","explanation":"A dominance model of dog–human relationships has been promoted by some dog trainers, such as on the television program Dog Whisperer.","tags":["영어 독해","reading comprehension","Dog","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56d62d1e1c85041400946f84","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"쉬움","question":"[Passage: Dog]\nAnother study of dogs' roles in families showed many dogs have set tasks or routines undertaken as family members, the most common of which was helping with the washing-up by licking the plates in the dishwasher, and bringing in the newspaper from the lawn. Increasingly, human family members are engaging in activities centered on the perceived needs and interests of the dog, or in which the dog is an integral partner, such as dog dancing and dog yoga.\n\n[Question]\nA study showed that a task dogs do is bringing in what from the lawn?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"newspaper","explanation":"Another study of dogs' roles in families showed many dogs have set tasks or routines undertaken as family members, the most common of which was helping with the washing-up by licking the plates in the dishwasher, and bringing in the newspaper from the lawn.","tags":["영어 독해","reading comprehension","Dog","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56d62d1e1c85041400946f85","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"쉬움","question":"[Passage: Dog]\nAnother study of dogs' roles in families showed many dogs have set tasks or routines undertaken as family members, the most common of which was helping with the washing-up by licking the plates in the dishwasher, and bringing in the newspaper from the lawn. Increasingly, human family members are engaging in activities centered on the perceived needs and interests of the dog, or in which the dog is an integral partner, such as dog dancing and dog yoga.\n\n[Question]\nDogs often help clean in the kitchen by licking what?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"plates","explanation":"Another study of dogs' roles in families showed many dogs have set tasks or routines undertaken as family members, the most common of which was helping with the washing-up by licking the plates in the dishwasher, and bringing in the newspaper from the lawn.","tags":["영어 독해","reading comprehension","Dog","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56d62d1e1c85041400946f86","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"쉬움","question":"[Passage: Dog]\nAnother study of dogs' roles in families showed many dogs have set tasks or routines undertaken as family members, the most common of which was helping with the washing-up by licking the plates in the dishwasher, and bringing in the newspaper from the lawn. Increasingly, human family members are engaging in activities centered on the perceived needs and interests of the dog, or in which the dog is an integral partner, such as dog dancing and dog yoga.\n\n[Question]\nIn addition to dog dancing, what is another activity that families are doing that is centered around their pet?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"dog yoga.","explanation":"Increasingly, human family members are engaging in activities centered on the perceived needs and interests of the dog, or in which the dog is an integral partner, such as dog dancing and dog yoga.","tags":["영어 독해","reading comprehension","Dog","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56e7460a00c9c71400d76f10","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"쉬움","question":"[Passage: Paper]\nThe pulp papermaking process is said to have been developed in China during the early 2nd century AD, possibly as early as the year 105 A.D., by the Han court eunuch Cai Lun, although the earliest archaeological fragments of paper derive from the 2nd century BC in China. The modern pulp and paper industry is global, with China leading its production and the United States right behind it.\n\n[Question]\nWhat country was the process developed in?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"China","explanation":"The pulp papermaking process is said to have been developed in China during the early 2nd century AD, possibly as early as the year 105 A.","tags":["영어 독해","reading comprehension","Paper","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56e7460a00c9c71400d76f11","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"쉬움","question":"[Passage: Paper]\nThe pulp papermaking process is said to have been developed in China during the early 2nd century AD, possibly as early as the year 105 A.D., by the Han court eunuch Cai Lun, although the earliest archaeological fragments of paper derive from the 2nd century BC in China. The modern pulp and paper industry is global, with China leading its production and the United States right behind it.\n\n[Question]\nWhat country is leading in production of paper?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"China","explanation":"The pulp papermaking process is said to have been developed in China during the early 2nd century AD, possibly as early as the year 105 A.","tags":["영어 독해","reading comprehension","Paper","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56e7460a00c9c71400d76f12","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"쉬움","question":"[Passage: Paper]\nThe pulp papermaking process is said to have been developed in China during the early 2nd century AD, possibly as early as the year 105 A.D., by the Han court eunuch Cai Lun, although the earliest archaeological fragments of paper derive from the 2nd century BC in China. The modern pulp and paper industry is global, with China leading its production and the United States right behind it.\n\n[Question]\nWhat country is the second largest produced of paper?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"United States","explanation":"The modern pulp and paper industry is global, with China leading its production and the United States right behind it.","tags":["영어 독해","reading comprehension","Paper","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56e7460a00c9c71400d76f13","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"쉬움","question":"[Passage: Paper]\nThe pulp papermaking process is said to have been developed in China during the early 2nd century AD, possibly as early as the year 105 A.D., by the Han court eunuch Cai Lun, although the earliest archaeological fragments of paper derive from the 2nd century BC in China. The modern pulp and paper industry is global, with China leading its production and the United States right behind it.\n\n[Question]\nWhich court eunuch was associated with the papermaking process?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"Cai Lun","explanation":", by the Han court eunuch Cai Lun, although the earliest archaeological fragments of paper derive from the 2nd century BC in China.","tags":["영어 독해","reading comprehension","Paper","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56e746fc00c9c71400d76f19","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"쉬움","question":"[Passage: Paper]\nThe oldest known archaeological fragments of the immediate precursor to modern paper, date to the 2nd century BC in China. The pulp papermaking process is ascribed to Cai Lun, a 2nd-century AD Han court eunuch. With paper as an effective substitute for silk in many applications, China could export silk in greater quantity, contributing to a Golden Age.\n\n[Question]\nWho is credited with the papermaking process?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"Cai Lun","explanation":"The pulp papermaking process is ascribed to Cai Lun, a 2nd-century AD Han court eunuch.","tags":["영어 독해","reading comprehension","Paper","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56e746fc00c9c71400d76f1b","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"쉬움","question":"[Passage: Paper]\nThe oldest known archaeological fragments of the immediate precursor to modern paper, date to the 2nd century BC in China. The pulp papermaking process is ascribed to Cai Lun, a 2nd-century AD Han court eunuch. With paper as an effective substitute for silk in many applications, China could export silk in greater quantity, contributing to a Golden Age.\n\n[Question]\nWhat material did paper replace upon its invention?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"silk","explanation":"With paper as an effective substitute for silk in many applications, China could export silk in greater quantity, contributing to a Golden Age.","tags":["영어 독해","reading comprehension","Paper","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56e746fc00c9c71400d76f1c","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"쉬움","question":"[Passage: Paper]\nThe oldest known archaeological fragments of the immediate precursor to modern paper, date to the 2nd century BC in China. The pulp papermaking process is ascribed to Cai Lun, a 2nd-century AD Han court eunuch. With paper as an effective substitute for silk in many applications, China could export silk in greater quantity, contributing to a Golden Age.\n\n[Question]\nWhich Age did the invention of the papermaking process contribute towards?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"Golden Age","explanation":"With paper as an effective substitute for silk in many applications, China could export silk in greater quantity, contributing to a Golden Age.","tags":["영어 독해","reading comprehension","Paper","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56e746fc00c9c71400d76f1d","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"쉬움","question":"[Passage: Paper]\nThe oldest known archaeological fragments of the immediate precursor to modern paper, date to the 2nd century BC in China. The pulp papermaking process is ascribed to Cai Lun, a 2nd-century AD Han court eunuch. With paper as an effective substitute for silk in many applications, China could export silk in greater quantity, contributing to a Golden Age.\n\n[Question]\nWhat century is the first papermaking process attributed to?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"2nd","explanation":"The oldest known archaeological fragments of the immediate precursor to modern paper, date to the 2nd century BC in China.","tags":["영어 독해","reading comprehension","Paper","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56e74a8e00c9c71400d76f5b","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Paper]\nIts knowledge and uses spread from China through the Middle East to medieval Europe in the 13th century, where the first water powered paper mills were built. Because of paper's introduction to the West through the city of Baghdad, it was first called bagdatikos. In the 19th century, industrial manufacture greatly lowered its cost, enabling mass exchange of information and contributing to significant cultural shifts. In 1844, the Canadian inventor Charles Fenerty and the German F. G. Keller independently developed processes for pulping wood fibres.\n\n[Question]\nIn what century did the papermaking process spread from China to Europe?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"13th","explanation":"Its knowledge and uses spread from China through the Middle East to medieval Europe in the 13th century, where the first water powered paper mills were built.","tags":["영어 독해","reading comprehension","Paper","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56e74a8e00c9c71400d76f5c","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Paper]\nIts knowledge and uses spread from China through the Middle East to medieval Europe in the 13th century, where the first water powered paper mills were built. Because of paper's introduction to the West through the city of Baghdad, it was first called bagdatikos. In the 19th century, industrial manufacture greatly lowered its cost, enabling mass exchange of information and contributing to significant cultural shifts. In 1844, the Canadian inventor Charles Fenerty and the German F. G. Keller independently developed processes for pulping wood fibres.\n\n[Question]\nWhich middle eastern city did the papermaking process to Europe from?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"Baghdad","explanation":"Because of paper's introduction to the West through the city of Baghdad, it was first called bagdatikos.","tags":["영어 독해","reading comprehension","Paper","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56fe016d761e401900d28c97","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Computer]\nThe ability to store and execute lists of instructions called programs makes computers extremely versatile, distinguishing them from calculators. The Church–Turing thesis is a mathematical statement of this versatility: any computer with a minimum capability (being Turing-complete) is, in principle, capable of performing the same tasks that any other computer can perform. Therefore, any type of computer (netbook, supercomputer, cellular automaton, etc.) is able to perform the same computational tasks, given enough time and storage capacity.\n\n[Question]\nThe ability to store and execute lists of instructions are called what?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"programs","explanation":"The ability to store and execute lists of instructions called programs makes computers extremely versatile, distinguishing them from calculators.","tags":["영어 독해","reading comprehension","Computer","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56fe016d761e401900d28c98","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Computer]\nThe ability to store and execute lists of instructions called programs makes computers extremely versatile, distinguishing them from calculators. The Church–Turing thesis is a mathematical statement of this versatility: any computer with a minimum capability (being Turing-complete) is, in principle, capable of performing the same tasks that any other computer can perform. Therefore, any type of computer (netbook, supercomputer, cellular automaton, etc.) is able to perform the same computational tasks, given enough time and storage capacity.\n\n[Question]\nThe mathematical statement of computers versatility is known as what?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"The Church–Turing thesis","explanation":"The Church–Turing thesis is a mathematical statement of this versatility: any computer with a minimum capability (being Turing-complete) is, in principle, capable of performing the same tasks that any other computer can perform.","tags":["영어 독해","reading comprehension","Computer","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56fe01af19033b140034ce31","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Computer]\nA computer does not need to be electronic, nor even have a processor, nor RAM, nor even a hard disk. While popular usage of the word \"computer\" is synonymous with a personal electronic computer, the modern definition of a computer is literally: \"A device that computes, especially a programmable [usually] electronic machine that performs high-speed mathematical or logical operations or that assembles, stores, correlates, or otherwise processes information.\" Any device which processes information qualifies as a computer, especially if the processing is purposeful.[citation needed]\n\n[Question]\nAll devices that can process information can qualify being called what?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"a computer","explanation":"\" Any device which processes information qualifies as a computer, especially if the processing is purposeful.","tags":["영어 독해","reading comprehension","Computer","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56fe022c19033b140034ce33","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"쉬움","question":"[Passage: Computer]\nHistorically, computers evolved from mechanical computers and eventually from vacuum tubes to transistors. However, conceptually computational systems as flexible as a personal computer can be built out of almost anything. For example, a computer can be made out of billiard balls (billiard ball computer); an often quoted example.[citation needed] More realistically, modern computers are made out of transistors made of photolithographed semiconductors.\n\n[Question]\nVacuum tubes in early computers were replaced by what?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"transistors","explanation":"Historically, computers evolved from mechanical computers and eventually from vacuum tubes to transistors.","tags":["영어 독해","reading comprehension","Computer","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56fe022c19033b140034ce34","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"쉬움","question":"[Passage: Computer]\nHistorically, computers evolved from mechanical computers and eventually from vacuum tubes to transistors. However, conceptually computational systems as flexible as a personal computer can be built out of almost anything. For example, a computer can be made out of billiard balls (billiard ball computer); an often quoted example.[citation needed] More realistically, modern computers are made out of transistors made of photolithographed semiconductors.\n\n[Question]\nTransistors are typically made up of what today?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"photolithographed semiconductors","explanation":"[citation needed] More realistically, modern computers are made out of transistors made of photolithographed semiconductors.","tags":["영어 독해","reading comprehension","Computer","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56fe022c19033b140034ce35","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"쉬움","question":"[Passage: Computer]\nHistorically, computers evolved from mechanical computers and eventually from vacuum tubes to transistors. However, conceptually computational systems as flexible as a personal computer can be built out of almost anything. For example, a computer can be made out of billiard balls (billiard ball computer); an often quoted example.[citation needed] More realistically, modern computers are made out of transistors made of photolithographed semiconductors.\n\n[Question]\nA computer that is made using pool balls is known as what?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"billiard ball computer)","explanation":"For example, a computer can be made out of billiard balls (billiard ball computer); an often quoted example.","tags":["영어 독해","reading comprehension","Computer","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56fe0329761e401900d28c9b","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Computer]\nThere is active research to make computers out of many promising new types of technology, such as optical computers, DNA computers, neural computers, and quantum computers. Most computers are universal, and are able to calculate any computable function, and are limited only by their memory capacity and operating speed. However different designs of computers can give very different performance for particular problems; for example quantum computers can potentially break some modern encryption algorithms (by quantum factoring) very quickly.\n\n[Question]\nWhat type of computer can break encryption algorithms quickly?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"quantum computers","explanation":"However different designs of computers can give very different performance for particular problems; for example quantum computers can potentially break some modern encryption algorithms (by quantum factoring) very quickly.","tags":["영어 독해","reading comprehension","Computer","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56fe0329761e401900d28c9c","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Computer]\nThere is active research to make computers out of many promising new types of technology, such as optical computers, DNA computers, neural computers, and quantum computers. Most computers are universal, and are able to calculate any computable function, and are limited only by their memory capacity and operating speed. However different designs of computers can give very different performance for particular problems; for example quantum computers can potentially break some modern encryption algorithms (by quantum factoring) very quickly.\n\n[Question]\nBy what method do quantum computers solve encryption algorithms quickly?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"quantum factoring","explanation":"However different designs of computers can give very different performance for particular problems; for example quantum computers can potentially break some modern encryption algorithms (by quantum factoring) very quickly.","tags":["영어 독해","reading comprehension","Computer","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56fe034c19033b140034ce39","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"쉬움","question":"[Passage: Computer]\nA computer will solve problems in exactly the way it is programmed to, without regard to efficiency, alternative solutions, possible shortcuts, or possible errors in the code. Computer programs that learn and adapt are part of the emerging field of artificial intelligence and machine learning.\n\n[Question]\nComputer programs that can learn are studied in what field?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"artificial intelligence","explanation":"Computer programs that learn and adapt are part of the emerging field of artificial intelligence and machine learning.","tags":["영어 독해","reading comprehension","Computer","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-56fe037c19033b140034ce3b","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"쉬움","question":"[Passage: Computer]\nThe term hardware covers all of those parts of a computer that are tangible objects. Circuits, displays, power supplies, cables, keyboards, printers and mice are all hardware.\n\n[Question]\nParts of a computer that are real objects are collectively known as what?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"hardware","explanation":"The term hardware covers all of those parts of a computer that are tangible objects.","tags":["영어 독해","reading comprehension","Computer","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-570cfff3fed7b91900d45bad","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Macintosh]\nThe Macintosh (/ˈmækᵻntɒʃ/ MAK-in-tosh; branded as Mac since 1997) is a series of personal computers (PCs) designed, developed, and marketed by Apple Inc. Steve Jobs introduced the original Macintosh computer on January 24, 1984. This was the first mass-market personal computer featuring an integral graphical user interface and mouse. This first model was later renamed to \"Macintosh 128k\" for uniqueness amongst a populous family of subsequently updated models which are also based on Apple's same proprietary architecture. Since 1998, Apple has largely phased out the Macintosh name in favor of \"Mac\", though the product family has been nicknamed \"Mac\" or \"the Mac\" since the development of the first model.\n\n[Question]\nWhen was the Macintosh branded as Mac?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"1997","explanation":"The Macintosh (/ˈmækᵻntɒʃ/ MAK-in-tosh; branded as Mac since 1997) is a series of personal computers (PCs) designed, developed, and marketed by Apple Inc.","tags":["영어 독해","reading comprehension","Macintosh","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-570cfff3fed7b91900d45bae","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Macintosh]\nThe Macintosh (/ˈmækᵻntɒʃ/ MAK-in-tosh; branded as Mac since 1997) is a series of personal computers (PCs) designed, developed, and marketed by Apple Inc. Steve Jobs introduced the original Macintosh computer on January 24, 1984. This was the first mass-market personal computer featuring an integral graphical user interface and mouse. This first model was later renamed to \"Macintosh 128k\" for uniqueness amongst a populous family of subsequently updated models which are also based on Apple's same proprietary architecture. Since 1998, Apple has largely phased out the Macintosh name in favor of \"Mac\", though the product family has been nicknamed \"Mac\" or \"the Mac\" since the development of the first model.\n\n[Question]\nWho designed, develped, and marketed the Mac computers?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"Apple Inc.","explanation":"The Macintosh (/ˈmækᵻntɒʃ/ MAK-in-tosh; branded as Mac since 1997) is a series of personal computers (PCs) designed, developed, and marketed by Apple Inc. Steve Jobs introduced the original Macintosh computer on January 24, 1984.","tags":["영어 독해","reading comprehension","Macintosh","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-570cfff3fed7b91900d45baf","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Macintosh]\nThe Macintosh (/ˈmækᵻntɒʃ/ MAK-in-tosh; branded as Mac since 1997) is a series of personal computers (PCs) designed, developed, and marketed by Apple Inc. Steve Jobs introduced the original Macintosh computer on January 24, 1984. This was the first mass-market personal computer featuring an integral graphical user interface and mouse. This first model was later renamed to \"Macintosh 128k\" for uniqueness amongst a populous family of subsequently updated models which are also based on Apple's same proprietary architecture. Since 1998, Apple has largely phased out the Macintosh name in favor of \"Mac\", though the product family has been nicknamed \"Mac\" or \"the Mac\" since the development of the first model.\n\n[Question]\nWhat did Steve Jobs introduce on January 24, 1984?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"original Macintosh computer","explanation":"Steve Jobs introduced the original Macintosh computer on January 24, 1984.","tags":["영어 독해","reading comprehension","Macintosh","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-570cfff3fed7b91900d45bb0","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Macintosh]\nThe Macintosh (/ˈmækᵻntɒʃ/ MAK-in-tosh; branded as Mac since 1997) is a series of personal computers (PCs) designed, developed, and marketed by Apple Inc. Steve Jobs introduced the original Macintosh computer on January 24, 1984. This was the first mass-market personal computer featuring an integral graphical user interface and mouse. This first model was later renamed to \"Macintosh 128k\" for uniqueness amongst a populous family of subsequently updated models which are also based on Apple's same proprietary architecture. Since 1998, Apple has largely phased out the Macintosh name in favor of \"Mac\", though the product family has been nicknamed \"Mac\" or \"the Mac\" since the development of the first model.\n\n[Question]\nWhat interface type did the original Macintosh include?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"integral graphical user","explanation":"This was the first mass-market personal computer featuring an integral graphical user interface and mouse.","tags":["영어 독해","reading comprehension","Macintosh","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-570cfff3fed7b91900d45bb1","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Macintosh]\nThe Macintosh (/ˈmækᵻntɒʃ/ MAK-in-tosh; branded as Mac since 1997) is a series of personal computers (PCs) designed, developed, and marketed by Apple Inc. Steve Jobs introduced the original Macintosh computer on January 24, 1984. This was the first mass-market personal computer featuring an integral graphical user interface and mouse. This first model was later renamed to \"Macintosh 128k\" for uniqueness amongst a populous family of subsequently updated models which are also based on Apple's same proprietary architecture. Since 1998, Apple has largely phased out the Macintosh name in favor of \"Mac\", though the product family has been nicknamed \"Mac\" or \"the Mac\" since the development of the first model.\n\n[Question]\nWhen did Apple begin phasing out Macintosh in favor of \"Mac\"?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"Since 1998","explanation":"Since 1998, Apple has largely phased out the Macintosh name in favor of \"Mac\", though the product family has been nicknamed \"Mac\" or \"the Mac\" since the development of the first model.","tags":["영어 독해","reading comprehension","Macintosh","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-570d0581b3d812140066d39d","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Macintosh]\nIn 1985, the combination of the Mac, Apple's LaserWriter printer, and Mac-specific software like Boston Software's MacPublisher and Aldus PageMaker enabled users to design, preview, and print page layouts complete with text and graphics—an activity to become known as desktop publishing. Initially, desktop publishing was unique to the Macintosh, but eventually became available for other platforms. Later, applications such as Macromedia FreeHand, QuarkXPress, and Adobe's Photoshop and Illustrator strengthened the Mac's position as a graphics computer and helped to expand the emerging desktop publishing market.\n\n[Question]\nWhen was the activity of desktop publishing first used?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"1985","explanation":"In 1985, the combination of the Mac, Apple's LaserWriter printer, and Mac-specific software like Boston Software's MacPublisher and Aldus PageMaker enabled users to design, preview, and print page layouts complete with text and graphics—an activity to become known as desktop publishing.","tags":["영어 독해","reading comprehension","Macintosh","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-570d0581b3d812140066d39e","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Macintosh]\nIn 1985, the combination of the Mac, Apple's LaserWriter printer, and Mac-specific software like Boston Software's MacPublisher and Aldus PageMaker enabled users to design, preview, and print page layouts complete with text and graphics—an activity to become known as desktop publishing. Initially, desktop publishing was unique to the Macintosh, but eventually became available for other platforms. Later, applications such as Macromedia FreeHand, QuarkXPress, and Adobe's Photoshop and Illustrator strengthened the Mac's position as a graphics computer and helped to expand the emerging desktop publishing market.\n\n[Question]\nWhat company was desktop publishing unique to at it's beginning?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"Macintosh","explanation":"Initially, desktop publishing was unique to the Macintosh, but eventually became available for other platforms.","tags":["영어 독해","reading comprehension","Macintosh","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-570d0581b3d812140066d39f","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Macintosh]\nIn 1985, the combination of the Mac, Apple's LaserWriter printer, and Mac-specific software like Boston Software's MacPublisher and Aldus PageMaker enabled users to design, preview, and print page layouts complete with text and graphics—an activity to become known as desktop publishing. Initially, desktop publishing was unique to the Macintosh, but eventually became available for other platforms. Later, applications such as Macromedia FreeHand, QuarkXPress, and Adobe's Photoshop and Illustrator strengthened the Mac's position as a graphics computer and helped to expand the emerging desktop publishing market.\n\n[Question]\nWhat three things were combined to develop desktop publishing?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"Mac, Apple's LaserWriter printer, and Mac-specific software like Boston Software's MacPublisher","explanation":"In 1985, the combination of the Mac, Apple's LaserWriter printer, and Mac-specific software like Boston Software's MacPublisher and Aldus PageMaker enabled users to design, preview, and print page layouts complete with text and graphics—an activity to become known as desktop publishing.","tags":["영어 독해","reading comprehension","Macintosh","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-570d0581b3d812140066d3a0","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Macintosh]\nIn 1985, the combination of the Mac, Apple's LaserWriter printer, and Mac-specific software like Boston Software's MacPublisher and Aldus PageMaker enabled users to design, preview, and print page layouts complete with text and graphics—an activity to become known as desktop publishing. Initially, desktop publishing was unique to the Macintosh, but eventually became available for other platforms. Later, applications such as Macromedia FreeHand, QuarkXPress, and Adobe's Photoshop and Illustrator strengthened the Mac's position as a graphics computer and helped to expand the emerging desktop publishing market.\n\n[Question]\nWhat did desktop publishing enable users to do?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"design, preview, and print page layouts complete with text and graphics","explanation":"In 1985, the combination of the Mac, Apple's LaserWriter printer, and Mac-specific software like Boston Software's MacPublisher and Aldus PageMaker enabled users to design, preview, and print page layouts complete with text and graphics—an activity to become known as desktop publishing.","tags":["영어 독해","reading comprehension","Macintosh","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-570d0581b3d812140066d3a1","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Macintosh]\nIn 1985, the combination of the Mac, Apple's LaserWriter printer, and Mac-specific software like Boston Software's MacPublisher and Aldus PageMaker enabled users to design, preview, and print page layouts complete with text and graphics—an activity to become known as desktop publishing. Initially, desktop publishing was unique to the Macintosh, but eventually became available for other platforms. Later, applications such as Macromedia FreeHand, QuarkXPress, and Adobe's Photoshop and Illustrator strengthened the Mac's position as a graphics computer and helped to expand the emerging desktop publishing market.\n\n[Question]\nWhat applications strengthened Mac's position as a graphics computer?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"Macromedia FreeHand, QuarkXPress, and Adobe's Photoshop and Illustrator","explanation":"Later, applications such as Macromedia FreeHand, QuarkXPress, and Adobe's Photoshop and Illustrator strengthened the Mac's position as a graphics computer and helped to expand the emerging desktop publishing market.","tags":["영어 독해","reading comprehension","Macintosh","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-5725eaa6ec44d21400f3d74e","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Montevideo]\nHospital Maciel is one of the oldest hospitals in Uruguay and stands on the block bounded by the streets Maciel, 25 de Mayo, Guaraní and Washington, with the main entrance at 25 de Mayo, 172. The land was originally donated in Spanish colonial times by philanthropist Francisco Antonio Maciel, who teamed up with Mateo Vidal to establish a hospital and charity. The first building was constructed between 1781 and 1788 and later expanded upon. The present building stems from the 1825 plans of José Toribio (son of Tomás Toribio) and later Bernardo Poncini (wing on the Guaraní street, 1859), Eduardo Canstatt (corner of Guaraní and 25 de Mayo) and Julián Masquelez (1889). The hospital has a chapel built in Greek style by Miguel Estévez in 1798.\n\n[Question]\nWho originally donated the land for Hospital Macie?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"Francisco Antonio Maciel","explanation":"The land was originally donated in Spanish colonial times by philanthropist Francisco Antonio Maciel, who teamed up with Mateo Vidal to establish a hospital and charity.","tags":["영어 독해","reading comprehension","Montevideo","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-5725eaa6ec44d21400f3d74f","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Montevideo]\nHospital Maciel is one of the oldest hospitals in Uruguay and stands on the block bounded by the streets Maciel, 25 de Mayo, Guaraní and Washington, with the main entrance at 25 de Mayo, 172. The land was originally donated in Spanish colonial times by philanthropist Francisco Antonio Maciel, who teamed up with Mateo Vidal to establish a hospital and charity. The first building was constructed between 1781 and 1788 and later expanded upon. The present building stems from the 1825 plans of José Toribio (son of Tomás Toribio) and later Bernardo Poncini (wing on the Guaraní street, 1859), Eduardo Canstatt (corner of Guaraní and 25 de Mayo) and Julián Masquelez (1889). The hospital has a chapel built in Greek style by Miguel Estévez in 1798.\n\n[Question]\nWhen was the first building of the Hospital Maciel established?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"between 1781 and 1788","explanation":"The first building was constructed between 1781 and 1788 and later expanded upon.","tags":["영어 독해","reading comprehension","Montevideo","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-5725ebb3ec44d21400f3d753","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Montevideo]\nHospital Vilardebó is the only psychiatric hospital in Montevideo. Named after the physician and naturalist Teodoro Vilardebó Matuliche, it opened 21 May 1880. The hospital was originally one of the best of Latin America and in 1915 grew to 1,500 inpatients. Today the hospital is very deteriorated, with broken walls and floors, lack of medicines, beds, and rooms for the personnel. It has an emergency service, outpatient, clinic and inpatient rooms and employs approximately 610 staff, psychologists, psychiatrists, social workers, administrators, guards, among others. The average patient age is 30 years; more than half of the patients arrive by court order; 42% suffer from schizophrenia, 18% from depression and mania, and there are also a high percentage of drug addicted patients.\n\n[Question]\nWhat is the only psychiatric hospital in Montevideo?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"Hospital Vilardebó","explanation":"Hospital Vilardebó is the only psychiatric hospital in Montevideo.","tags":["영어 독해","reading comprehension","Montevideo","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-5725ebb3ec44d21400f3d754","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Montevideo]\nHospital Vilardebó is the only psychiatric hospital in Montevideo. Named after the physician and naturalist Teodoro Vilardebó Matuliche, it opened 21 May 1880. The hospital was originally one of the best of Latin America and in 1915 grew to 1,500 inpatients. Today the hospital is very deteriorated, with broken walls and floors, lack of medicines, beds, and rooms for the personnel. It has an emergency service, outpatient, clinic and inpatient rooms and employs approximately 610 staff, psychologists, psychiatrists, social workers, administrators, guards, among others. The average patient age is 30 years; more than half of the patients arrive by court order; 42% suffer from schizophrenia, 18% from depression and mania, and there are also a high percentage of drug addicted patients.\n\n[Question]\nWho is Hospital Vilardebo named after?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"Teodoro Vilardebó Matuliche","explanation":"Named after the physician and naturalist Teodoro Vilardebó Matuliche, it opened 21 May 1880.","tags":["영어 독해","reading comprehension","Montevideo","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-5725ebb3ec44d21400f3d755","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Montevideo]\nHospital Vilardebó is the only psychiatric hospital in Montevideo. Named after the physician and naturalist Teodoro Vilardebó Matuliche, it opened 21 May 1880. The hospital was originally one of the best of Latin America and in 1915 grew to 1,500 inpatients. Today the hospital is very deteriorated, with broken walls and floors, lack of medicines, beds, and rooms for the personnel. It has an emergency service, outpatient, clinic and inpatient rooms and employs approximately 610 staff, psychologists, psychiatrists, social workers, administrators, guards, among others. The average patient age is 30 years; more than half of the patients arrive by court order; 42% suffer from schizophrenia, 18% from depression and mania, and there are also a high percentage of drug addicted patients.\n\n[Question]\nWhen did the Hospital Vilardebo open?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"21 May 1880","explanation":"Named after the physician and naturalist Teodoro Vilardebó Matuliche, it opened 21 May 1880.","tags":["영어 독해","reading comprehension","Montevideo","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-5725ebb3ec44d21400f3d756","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Montevideo]\nHospital Vilardebó is the only psychiatric hospital in Montevideo. Named after the physician and naturalist Teodoro Vilardebó Matuliche, it opened 21 May 1880. The hospital was originally one of the best of Latin America and in 1915 grew to 1,500 inpatients. Today the hospital is very deteriorated, with broken walls and floors, lack of medicines, beds, and rooms for the personnel. It has an emergency service, outpatient, clinic and inpatient rooms and employs approximately 610 staff, psychologists, psychiatrists, social workers, administrators, guards, among others. The average patient age is 30 years; more than half of the patients arrive by court order; 42% suffer from schizophrenia, 18% from depression and mania, and there are also a high percentage of drug addicted patients.\n\n[Question]\nHow many inpatients did the the Hospital Vilardebo have in 1915?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"1,500 inpatients","explanation":"The hospital was originally one of the best of Latin America and in 1915 grew to 1,500 inpatients.","tags":["영어 독해","reading comprehension","Montevideo","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-5725b87189a1e219009abd66","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Poultry]\nPoultry (/ˌpoʊltriː/) are domesticated birds kept by humans for the eggs they produce, their meat, their feathers, or sometimes as pets. These birds are most typically members of the superorder Galloanserae (fowl), especially the order Galliformes (which includes chickens, quails and turkeys) and the family Anatidae, in order Anseriformes, commonly known as \"waterfowl\" and including domestic ducks and domestic geese. Poultry also includes other birds that are killed for their meat, such as the young of pigeons (known as squabs) but does not include similar wild birds hunted for sport or food and known as game. The word \"poultry\" comes from the French/Norman word poule, itself derived from the Latin word pullus, which means small animal.\n\n[Question]\nWhat is the significance of poultry in the lives of humans?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"kept by humans for the eggs they produce, their meat, their feathers, or sometimes as pets.","explanation":"Poultry (/ˌpoʊltriː/) are domesticated birds kept by humans for the eggs they produce, their meat, their feathers, or sometimes as pets. These birds are most typically members of the superorder Galloanserae (fowl), especially the order Galliformes (which includes chickens, quails and turkeys) and the family Anatidae, in order Anseriformes, commonly known as \"waterfowl\" and including domestic ducks and domestic geese.","tags":["영어 독해","reading comprehension","Poultry","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-5725b87189a1e219009abd67","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Poultry]\nPoultry (/ˌpoʊltriː/) are domesticated birds kept by humans for the eggs they produce, their meat, their feathers, or sometimes as pets. These birds are most typically members of the superorder Galloanserae (fowl), especially the order Galliformes (which includes chickens, quails and turkeys) and the family Anatidae, in order Anseriformes, commonly known as \"waterfowl\" and including domestic ducks and domestic geese. Poultry also includes other birds that are killed for their meat, such as the young of pigeons (known as squabs) but does not include similar wild birds hunted for sport or food and known as game. The word \"poultry\" comes from the French/Norman word poule, itself derived from the Latin word pullus, which means small animal.\n\n[Question]\nAre all domesticated and wild birds classified as poultry  ?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"but does not include similar wild birds hunted for sport or food and known as game.","explanation":"Poultry also includes other birds that are killed for their meat, such as the young of pigeons (known as squabs) but does not include similar wild birds hunted for sport or food and known as game. The word \"poultry\" comes from the French/Norman word poule, itself derived from the Latin word pullus, which means small animal.","tags":["영어 독해","reading comprehension","Poultry","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-5725b87189a1e219009abd68","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Poultry]\nPoultry (/ˌpoʊltriː/) are domesticated birds kept by humans for the eggs they produce, their meat, their feathers, or sometimes as pets. These birds are most typically members of the superorder Galloanserae (fowl), especially the order Galliformes (which includes chickens, quails and turkeys) and the family Anatidae, in order Anseriformes, commonly known as \"waterfowl\" and including domestic ducks and domestic geese. Poultry also includes other birds that are killed for their meat, such as the young of pigeons (known as squabs) but does not include similar wild birds hunted for sport or food and known as game. The word \"poultry\" comes from the French/Norman word poule, itself derived from the Latin word pullus, which means small animal.\n\n[Question]\nWhat types of  birds are most commonly considered poultry?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"chickens, quails and turkeys","explanation":"These birds are most typically members of the superorder Galloanserae (fowl), especially the order Galliformes (which includes chickens, quails and turkeys) and the family Anatidae, in order Anseriformes, commonly known as \"waterfowl\" and including domestic ducks and domestic geese.","tags":["영어 독해","reading comprehension","Poultry","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-5725b87189a1e219009abd69","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Poultry]\nPoultry (/ˌpoʊltriː/) are domesticated birds kept by humans for the eggs they produce, their meat, their feathers, or sometimes as pets. These birds are most typically members of the superorder Galloanserae (fowl), especially the order Galliformes (which includes chickens, quails and turkeys) and the family Anatidae, in order Anseriformes, commonly known as \"waterfowl\" and including domestic ducks and domestic geese. Poultry also includes other birds that are killed for their meat, such as the young of pigeons (known as squabs) but does not include similar wild birds hunted for sport or food and known as game. The word \"poultry\" comes from the French/Norman word poule, itself derived from the Latin word pullus, which means small animal.\n\n[Question]\nWas the Latin word for poultry also used to decribe other small animals as opposed to any poulty?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"from the Latin word pullus, which means small animal.","explanation":"The word \"poultry\" comes from the French/Norman word poule, itself derived from the Latin word pullus, which means small animal.","tags":["영어 독해","reading comprehension","Poultry","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-57276f4cdd62a815002e9cc9","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Cotton]\nIn addition to concerns over subsidies, the cotton industries of some countries are criticized for employing child labor and damaging workers' health by exposure to pesticides used in production. The Environmental Justice Foundation has campaigned against the prevalent use of forced child and adult labor in cotton production in Uzbekistan, the world's third largest cotton exporter. The international production and trade situation has led to \"fair trade\" cotton clothing and footwear, joining a rapidly growing market for organic clothing, fair fashion or \"ethical fashion\". The fair trade system was initiated in 2005 with producers from Cameroon, Mali and Senegal.\n\n[Question]\nWhere does Uzbekistan rank as a cotton exporter?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"third largest","explanation":"The Environmental Justice Foundation has campaigned against the prevalent use of forced child and adult labor in cotton production in Uzbekistan, the world's third largest cotton exporter.","tags":["영어 독해","reading comprehension","Cotton","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-57276f4cdd62a815002e9cca","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Cotton]\nIn addition to concerns over subsidies, the cotton industries of some countries are criticized for employing child labor and damaging workers' health by exposure to pesticides used in production. The Environmental Justice Foundation has campaigned against the prevalent use of forced child and adult labor in cotton production in Uzbekistan, the world's third largest cotton exporter. The international production and trade situation has led to \"fair trade\" cotton clothing and footwear, joining a rapidly growing market for organic clothing, fair fashion or \"ethical fashion\". The fair trade system was initiated in 2005 with producers from Cameroon, Mali and Senegal.\n\n[Question]\nWhat system was started in 2005 to deal with organic and ethically produced products?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"fair trade","explanation":"The fair trade system was initiated in 2005 with producers from Cameroon, Mali and Senegal.","tags":["영어 독해","reading comprehension","Cotton","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-572771b85951b619008f8a07","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"응용","question":"[Passage: Cotton]\nA public genome sequencing effort of cotton was initiated in 2007 by a consortium of public researchers. They agreed on a strategy to sequence the genome of cultivated, tetraploid cotton. \"Tetraploid\" means that cultivated cotton actually has two separate genomes within its nucleus, referred to as the A and D genomes. The sequencing consortium first agreed to sequence the D-genome relative of cultivated cotton (G. raimondii, a wild Central American cotton species) because of its small size and limited number of repetitive elements. It is nearly one-third the number of bases of tetraploid cotton (AD), and each chromosome is only present once.[clarification needed] The A genome of G. arboreum would be sequenced next. Its genome is roughly twice the size of G. raimondii's. Part of the difference in size between the two genomes is the amplification of retrotransposons (GORGE). Once both diploid genomes are assembled, then research could begin sequencing the actual genomes of cultivated cotton varieties. This strategy is out of necessity; if one were to sequence the tetraploid genome without model diploid genomes, the euchromatic DNA sequences of the AD genomes would co-assemble and the repetitive elements of AD genomes would assembly independently into A and D sequences respectively. Then there would be no way to untangle the mess of AD sequences without comparing them to their diploid counterparts.\n\n[Question]\nWhat is the final sequencing goal of sequencing diploid cotton genomes first ?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"tetraploid cotton","explanation":"They agreed on a strategy to sequence the genome of cultivated, tetraploid cotton.","tags":["영어 독해","reading comprehension","Cotton","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-572771b85951b619008f8a08","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"응용","question":"[Passage: Cotton]\nA public genome sequencing effort of cotton was initiated in 2007 by a consortium of public researchers. They agreed on a strategy to sequence the genome of cultivated, tetraploid cotton. \"Tetraploid\" means that cultivated cotton actually has two separate genomes within its nucleus, referred to as the A and D genomes. The sequencing consortium first agreed to sequence the D-genome relative of cultivated cotton (G. raimondii, a wild Central American cotton species) because of its small size and limited number of repetitive elements. It is nearly one-third the number of bases of tetraploid cotton (AD), and each chromosome is only present once.[clarification needed] The A genome of G. arboreum would be sequenced next. Its genome is roughly twice the size of G. raimondii's. Part of the difference in size between the two genomes is the amplification of retrotransposons (GORGE). Once both diploid genomes are assembled, then research could begin sequencing the actual genomes of cultivated cotton varieties. This strategy is out of necessity; if one were to sequence the tetraploid genome without model diploid genomes, the euchromatic DNA sequences of the AD genomes would co-assemble and the repetitive elements of AD genomes would assembly independently into A and D sequences respectively. Then there would be no way to untangle the mess of AD sequences without comparing them to their diploid counterparts.\n\n[Question]\nWhat type of cotton has two separate genomes within its nucleus? ","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"Tetraploid","explanation":"\"Tetraploid\" means that cultivated cotton actually has two separate genomes within its nucleus, referred to as the A and D genomes.","tags":["영어 독해","reading comprehension","Cotton","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-572771b85951b619008f8a09","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"응용","question":"[Passage: Cotton]\nA public genome sequencing effort of cotton was initiated in 2007 by a consortium of public researchers. They agreed on a strategy to sequence the genome of cultivated, tetraploid cotton. \"Tetraploid\" means that cultivated cotton actually has two separate genomes within its nucleus, referred to as the A and D genomes. The sequencing consortium first agreed to sequence the D-genome relative of cultivated cotton (G. raimondii, a wild Central American cotton species) because of its small size and limited number of repetitive elements. It is nearly one-third the number of bases of tetraploid cotton (AD), and each chromosome is only present once.[clarification needed] The A genome of G. arboreum would be sequenced next. Its genome is roughly twice the size of G. raimondii's. Part of the difference in size between the two genomes is the amplification of retrotransposons (GORGE). Once both diploid genomes are assembled, then research could begin sequencing the actual genomes of cultivated cotton varieties. This strategy is out of necessity; if one were to sequence the tetraploid genome without model diploid genomes, the euchromatic DNA sequences of the AD genomes would co-assemble and the repetitive elements of AD genomes would assembly independently into A and D sequences respectively. Then there would be no way to untangle the mess of AD sequences without comparing them to their diploid counterparts.\n\n[Question]\nWhen did a group of researchers decide to sequence the genomic structure of tetraploid cotton?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"2007","explanation":"A public genome sequencing effort of cotton was initiated in 2007 by a consortium of public researchers.","tags":["영어 독해","reading comprehension","Cotton","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-572771b85951b619008f8a0a","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"응용","question":"[Passage: Cotton]\nA public genome sequencing effort of cotton was initiated in 2007 by a consortium of public researchers. They agreed on a strategy to sequence the genome of cultivated, tetraploid cotton. \"Tetraploid\" means that cultivated cotton actually has two separate genomes within its nucleus, referred to as the A and D genomes. The sequencing consortium first agreed to sequence the D-genome relative of cultivated cotton (G. raimondii, a wild Central American cotton species) because of its small size and limited number of repetitive elements. It is nearly one-third the number of bases of tetraploid cotton (AD), and each chromosome is only present once.[clarification needed] The A genome of G. arboreum would be sequenced next. Its genome is roughly twice the size of G. raimondii's. Part of the difference in size between the two genomes is the amplification of retrotransposons (GORGE). Once both diploid genomes are assembled, then research could begin sequencing the actual genomes of cultivated cotton varieties. This strategy is out of necessity; if one were to sequence the tetraploid genome without model diploid genomes, the euchromatic DNA sequences of the AD genomes would co-assemble and the repetitive elements of AD genomes would assembly independently into A and D sequences respectively. Then there would be no way to untangle the mess of AD sequences without comparing them to their diploid counterparts.\n\n[Question]\nWhat type of genome must be sequenced first to prevent confusion before the tetraploid form?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"diploid","explanation":"Once both diploid genomes are assembled, then research could begin sequencing the actual genomes of cultivated cotton varieties.","tags":["영어 독해","reading comprehension","Cotton","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-572771b85951b619008f8a0b","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"응용","question":"[Passage: Cotton]\nA public genome sequencing effort of cotton was initiated in 2007 by a consortium of public researchers. They agreed on a strategy to sequence the genome of cultivated, tetraploid cotton. \"Tetraploid\" means that cultivated cotton actually has two separate genomes within its nucleus, referred to as the A and D genomes. The sequencing consortium first agreed to sequence the D-genome relative of cultivated cotton (G. raimondii, a wild Central American cotton species) because of its small size and limited number of repetitive elements. It is nearly one-third the number of bases of tetraploid cotton (AD), and each chromosome is only present once.[clarification needed] The A genome of G. arboreum would be sequenced next. Its genome is roughly twice the size of G. raimondii's. Part of the difference in size between the two genomes is the amplification of retrotransposons (GORGE). Once both diploid genomes are assembled, then research could begin sequencing the actual genomes of cultivated cotton varieties. This strategy is out of necessity; if one were to sequence the tetraploid genome without model diploid genomes, the euchromatic DNA sequences of the AD genomes would co-assemble and the repetitive elements of AD genomes would assembly independently into A and D sequences respectively. Then there would be no way to untangle the mess of AD sequences without comparing them to their diploid counterparts.\n\n[Question]\nIn order to understand the tetraploid forms, what must be used as a comparison in cotton gene sequencing?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"diploid counterparts","explanation":"Then there would be no way to untangle the mess of AD sequences without comparing them to their diploid counterparts.","tags":["영어 독해","reading comprehension","Cotton","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-57277399708984140094dde3","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Cotton]\nThe public sector effort continues with the goal to create a high-quality, draft genome sequence from reads generated by all sources. The public-sector effort has generated Sanger reads of BACs, fosmids, and plasmids as well as 454 reads. These later types of reads will be instrumental in assembling an initial draft of the D genome. In 2010, two companies (Monsanto and Illumina), completed enough Illumina sequencing to cover the D genome of G. raimondii about 50x. They announced that they would donate their raw reads to the public. This public relations effort gave them some recognition for sequencing the cotton genome. Once the D genome is assembled from all of this raw material, it will undoubtedly assist in the assembly of the AD genomes of cultivated varieties of cotton, but a lot of hard work remains.\n\n[Question]\nWhat companies finished much of the sequencing of the D genome?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"Monsanto and Illumina","explanation":"In 2010, two companies (Monsanto and Illumina), completed enough Illumina sequencing to cover the D genome of G.","tags":["영어 독해","reading comprehension","Cotton","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-57277399708984140094dde4","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Cotton]\nThe public sector effort continues with the goal to create a high-quality, draft genome sequence from reads generated by all sources. The public-sector effort has generated Sanger reads of BACs, fosmids, and plasmids as well as 454 reads. These later types of reads will be instrumental in assembling an initial draft of the D genome. In 2010, two companies (Monsanto and Illumina), completed enough Illumina sequencing to cover the D genome of G. raimondii about 50x. They announced that they would donate their raw reads to the public. This public relations effort gave them some recognition for sequencing the cotton genome. Once the D genome is assembled from all of this raw material, it will undoubtedly assist in the assembly of the AD genomes of cultivated varieties of cotton, but a lot of hard work remains.\n\n[Question]\nWhen was the sequencing of D genome of G.  raimondii mostly completed?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"2010","explanation":"In 2010, two companies (Monsanto and Illumina), completed enough Illumina sequencing to cover the D genome of G.","tags":["영어 독해","reading comprehension","Cotton","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-57277399708984140094dde5","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"보통","question":"[Passage: Cotton]\nThe public sector effort continues with the goal to create a high-quality, draft genome sequence from reads generated by all sources. The public-sector effort has generated Sanger reads of BACs, fosmids, and plasmids as well as 454 reads. These later types of reads will be instrumental in assembling an initial draft of the D genome. In 2010, two companies (Monsanto and Illumina), completed enough Illumina sequencing to cover the D genome of G. raimondii about 50x. They announced that they would donate their raw reads to the public. This public relations effort gave them some recognition for sequencing the cotton genome. Once the D genome is assembled from all of this raw material, it will undoubtedly assist in the assembly of the AD genomes of cultivated varieties of cotton, but a lot of hard work remains.\n\n[Question]\nWhat did Monsanto and Illumina say they would do with the research?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"donate","explanation":"They announced that they would donate their raw reads to the public.","tags":["영어 독해","reading comprehension","Cotton","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-5727b1c23acd2414000de9ee","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"응용","question":"[Passage: North Carolina]\nNorth Carolinians enjoy outdoor recreation utilizing numerous local bike paths, 34 state parks, and 14 national parks. National Park Service units include the Appalachian National Scenic Trail, the Blue Ridge Parkway, Cape Hatteras National Seashore, Cape Lookout National Seashore, Carl Sandburg Home National Historic Site at Flat Rock, Fort Raleigh National Historic Site at Manteo, Great Smoky Mountains National Park, Guilford Courthouse National Military Park in Greensboro, Moores Creek National Battlefield near Currie in Pender County, the Overmountain Victory National Historic Trail, Old Salem National Historic Site in Winston-Salem, the Trail of Tears National Historic Trail, and Wright Brothers National Memorial in Kill Devil Hills. National Forests include Uwharrie National Forest in central North Carolina, Croatan National Forest in Eastern North Carolina, Pisgah National Forest in the northern mountains, and Nantahala National Forest in the southwestern part of the state.\n\n[Question]\nHow many national parks are in North Carolina?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"14","explanation":"North Carolinians enjoy outdoor recreation utilizing numerous local bike paths, 34 state parks, and 14 national parks.","tags":["영어 독해","reading comprehension","North Carolina","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-5727b1c23acd2414000de9ef","subject":"영어","unit":"영어 독해","problem_type":"독해형","difficulty":"응용","question":"[Passage: North Carolina]\nNorth Carolinians enjoy outdoor recreation utilizing numerous local bike paths, 34 state parks, and 14 national parks. National Park Service units include the Appalachian National Scenic Trail, the Blue Ridge Parkway, Cape Hatteras National Seashore, Cape Lookout National Seashore, Carl Sandburg Home National Historic Site at Flat Rock, Fort Raleigh National Historic Site at Manteo, Great Smoky Mountains National Park, Guilford Courthouse National Military Park in Greensboro, Moores Creek National Battlefield near Currie in Pender County, the Overmountain Victory National Historic Trail, Old Salem National Historic Site in Winston-Salem, the Trail of Tears National Historic Trail, and Wright Brothers National Memorial in Kill Devil Hills. National Forests include Uwharrie National Forest in central North Carolina, Croatan National Forest in Eastern North Carolina, Pisgah National Forest in the northern mountains, and Nantahala National Forest in the southwestern part of the state.\n\n[Question]\nWhere is the Uwharrie national Forest located?","hint":"Find the sentence in the passage that uses the same key idea as the question.","answer":"central North Carolina","explanation":"National Forests include Uwharrie National Forest in central North Carolina, Croatan National Forest in Eastern North Carolina, Pisgah National Forest in the northern mountains, and Nantahala National Forest in the southwestern part of the state.","tags":["영어 독해","reading comprehension","North Carolina","SQuAD","CC BY-SA 4.0"],"source_name":"Stanford Question Answering Dataset (SQuAD)","source_author":"Pranav Rajpurkar, Jian Zhang, Konstantin Lopyrev, and Percy Liang","source_url":"https://rajpurkar.github.io/SQuAD-explorer/","license":"CC BY-SA 4.0","attribution":"Adapted from the Stanford Question Answering Dataset (SQuAD), licensed under CC BY-SA 4.0. Passage sources originate from Wikipedia; original English text retained."},{"code":"squad-5727b1c23acd2414000de9f0","sub